package cl.duoc.tienda.carrito.model;
import jakarta.persistence.*;
@Entity @Table(name="carritos") public class Carrito { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private Long usuarioId; private Long productoId; private Integer cantidad; public Carrito(){} public Carrito(Long usuarioId, Long productoId, Integer cantidad){this.usuarioId=usuarioId; this.productoId=productoId; this.cantidad=cantidad;} public Long getId(){return id;} public void setId(Long v){id=v;} public Long getUsuarioId(){return usuarioId;} public void setUsuarioId(Long v){usuarioId=v;} public Long getProductoId(){return productoId;} public void setProductoId(Long v){productoId=v;} public Integer getCantidad(){return cantidad;} public void setCantidad(Integer v){cantidad=v;} }
